    out = [row[:] for row in grid]
    # Isolated marker projects its color toward the edge segment; replace the
    # marker by 4. The segment color fills the gap.
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(r.count(c) for r in grid))
    for y in range(h):
        for x in range(w):
            c = grid[y][x]
            if c == bg or y in (0,h-1) or x in (0,w-1):
                continue
            for edge, step in ((0,-1),(w-1,1)):
                if grid[y][edge] != bg:
                    for xx in range(edge+1, x):
                        if grid[y][xx] == bg: out[y][xx] = grid[y][edge]
                    out[y][x] = 4
                    break
            else:
                for edge, step in ((0,-1),(h-1,1)):
                    if grid[edge][x] != bg:
                        for yy in range(edge+1,y):
                            if grid[yy][x] == bg: out[yy][x] = grid[edge][x]
                        out[y][x] = 4
                        break
    return out
